  "Scan":               { "zh-TW": "掃描", "zh-CN": "扫描", "ja": "スキャン", "ko": "스캔", "es": "Escanear" },
  "Scan serial number with camera (ALT+V screen)": { "zh-TW": "以攝影機掃描序號（ALT+V 畫面）", "zh-CN": "用摄像头扫描序列号（ALT+V 画面）", "ja": "カメラでシリアル番号を読み取り（ALT+V 画面）", "ko": "카메라로 시리얼 번호 스캔 (ALT+V 화면)", "es": "Escanear número de serie con la cámara (pantalla ALT+V)" },
  "Serial number capture": { "zh-TW": "序號擷取", "zh-CN": "序列号捕获", "ja": "シリアル番号キャプチャ", "ko": "시리얼 번호 캡처", "es": "Captura del número de serie" },
  "On the Chromebook press ALT+V at the sign-in screen, then point this camera at its screen. The serial number is detected automatically.": { "zh-TW": "請在 Chromebook 登入畫面按 ALT+V 顯示序號，然後將攝影機對準其螢幕，系統會自動辨識序號。", "zh-CN": "请在 Chromebook 登录界面按 ALT+V 显示序列号，然后将摄像头对准其屏幕，系统会自动识别序列号。", "ja": "Chromebook のログイン画面で ALT+V を押してシリアル番号を表示し、このカメラを画面に向けてください。自動的に認識されます。", "ko": "Chromebook 로그인 화면에서 ALT+V 를 눌러 시리얼 번호를 표시한 뒤 이 카메라를 화면에 비추세요. 자동으로 인식됩니다.", "es": "En el Chromebook pulse ALT+V en la pantalla de inicio de sesión y apunte esta cámara a su pantalla. El número de serie se detecta automáticamente." },
  "Starting camera…":   { "zh-TW": "正在啟動攝影機…", "zh-CN": "正在启动摄像头…", "ja": "カメラを起動中…", "ko": "카메라 시작 중…", "es": "Iniciando cámara…" },
  "Loading OCR engine…": { "zh-TW": "正在載入 OCR 引擎…", "zh-CN": "正在加载 OCR 引擎…", "ja": "OCR エンジンを読み込み中…", "ko": "OCR 엔진 로딩 중…", "es": "Cargando motor OCR…" },
  "Scanning… hold the Chromebook screen steady": { "zh-TW": "掃描中… 請穩定對準 Chromebook 螢幕", "zh-CN": "扫描中… 请稳定对准 Chromebook 屏幕", "ja": "スキャン中… Chromebook の画面を安定させてください", "ko": "스캔 중… Chromebook 화면을 고정해 주세요", "es": "Escaneando… mantenga estable la pantalla del Chromebook" },
  "No serial number detected yet — adjust distance / focus.": { "zh-TW": "尚未偵測到序號 — 請調整距離／對焦。", "zh-CN": "尚未检测到序列号 — 请调整距离／对焦。", "ja": "シリアル番号が未検出 — 距離やピントを調整してください。", "ko": "시리얼 번호가 감지되지 않음 — 거리/초점을 조정하세요.", "es": "Aún no se detecta el número de serie — ajuste la distancia / el enfoque." },
  "SN: detected — reading the number, hold steady…": { "zh-TW": "已偵測到 SN: — 正在讀取序號，請保持穩定…", "zh-CN": "已检测到 SN: — 正在读取序列号，请保持稳定…", "ja": "SN: を検出 — 番号を読み取り中、そのまま保持してください…", "ko": "SN: 감지됨 — 번호를 읽는 중, 그대로 유지하세요…", "es": "SN: detectado — leyendo el número, mantenga estable…" },
  "SN: detected — hold steady for {s} more second(s)…": { "zh-TW": "已偵測到 SN:！請保持穩定再 {s} 秒…", "zh-CN": "已检测到 SN:！请保持稳定再 {s} 秒…", "ja": "SN: を検出！あと {s} 秒そのまま保持してください…", "ko": "SN: 감지됨! {s}초 더 그대로 유지하세요…", "es": "¡SN: detectado! Mantenga estable {s} segundo(s) más…" },
  "Capturing — sending image to server for OCR…": { "zh-TW": "擷取中 — 正在將影像傳送至伺服器進行 OCR…", "zh-CN": "捕获中 — 正在将图像发送至服务器进行 OCR…", "ja": "キャプチャ中 — 画像をサーバーに送信して OCR 実行中…", "ko": "캐처 중 — 이미지를 서버로 보내 OCR 수행 중…", "es": "Capturando — enviando la imagen al servidor para OCR…" },
  "Server OCR could not read the serial — hold steady, retrying…": { "zh-TW": "伺服器 OCR 無法讀取序號 — 請保持穩定，重新嘗試中…", "zh-CN": "服务器 OCR 无法读取序列号 — 请保持稳定，重试中…", "ja": "サーバー OCR が番号を読み取れません — そのまま保持して再試行中…", "ko": "서버 OCR이 번호를 읽지 못함 — 그대로 유지하며 재시도 중…", "es": "El OCR del servidor no pudo leer el número — mantenga estable, reintentando…" },
  "Waiting for the “SN:” line — point the camera at the ALT+V screen.": { "zh-TW": "等待「SN:」字樣出現 — 請將攝影機對準 ALT+V 畫面。", "zh-CN": "等待“SN:”字样出现 — 请将摄像头对准 ALT+V 画面。", "ja": "「SN:」の表示待ち — ALT+V 画面にカメラを向けてください。", "ko": "“SN:” 표시 대기 중 — ALT+V 화면에 카메라를 비추세요.", "es": "Esperando la línea “SN:” — apunte la cámara a la pantalla ALT+V." },
  "Capture now":        { "zh-TW": "立即拍攝", "zh-CN": "立即拍摄", "ja": "今すぐ撮影", "ko": "지금 촬영", "es": "Capturar ahora" },
  "Camera unavailable — check permission / device.": { "zh-TW": "攝影機無法使用 — 請檢查權限／裝置。", "zh-CN": "摄像头不可用 — 请检查权限／设备。", "ja": "カメラを利用できません — 権限／デバイスを確認してください。", "ko": "카메라를 사용할 수 없음 — 권한/장치를 확인하세요.", "es": "Cámara no disponible — compruebe permisos / dispositivo." },
  "OCR engine could not be loaded — check the internet connection.": { "zh-TW": "無法載入 OCR 引擎 — 請檢查網路連線。", "zh-CN": "无法加载 OCR 引擎 — 请检查网络连接。", "ja": "OCR エンジンを読み込めません — インターネット接続を確認してください。", "ko": "OCR 엔진을 불러올 수 없음 — 인터넷 연결을 확인하세요.", "es": "No se pudo cargar el motor OCR — compruebe la conexión a internet." },
  "Serial number captured": { "zh-TW": "已擷取序號", "zh-CN": "已捕获序列号", "ja": "シリアル番号を取得しました", "ko": "시리얼 번호 캡처 완료", "es": "Número de serie capturado" },  "Operator identity capture": { "zh-TW": "操作員身份擷取", "zh-CN": "操作员身份捕获", "ja": "作業者の本人確認キャプチャ", "ko": "작업자 신원 캐처", "es": "Captura de identidad del operador" },
