let CUR_LANG = localStorage.getItem("nexacrew_lang") || "en";
if (!LANGS[CUR_LANG]) CUR_LANG = "en";

/* translate an English source string into the current language */
function t(s) {
  if (CUR_LANG === "en") return s;
  const row = I18N[s];
  return (row && row[CUR_LANG]) || s;
}

/* rewrite static chrome (sidebar, auth screen) — emoji prefixes are kept */
function applyI18n() {
  document.documentElement.lang = CUR_LANG;
  document.querySelectorAll(".nav-group").forEach(el => {
    if (!el.dataset.i18n) el.dataset.i18n = el.textContent.trim();
    el.textContent = t(el.dataset.i18n);
  });
  document.querySelectorAll(".nav-item").forEach(el => {
    // first text node only (keeps badge <span> children intact)
    const node = [...el.childNodes].find(n => n.nodeType === 3 && n.textContent.trim());
    if (!node) return;
    if (!el.dataset.i18n) {
      const m = node.textContent.trim().match(/^(\S+)\s+(.*)$/); // emoji + label
      el.dataset.i18nEmoji = m ? m[1] : "";
      el.dataset.i18n = m ? m[2] : node.textContent.trim();
    }
    node.textContent = (el.dataset.i18nEmoji ? el.dataset.i18nEmoji + " " : "") + t(el.dataset.i18n) + " ";
  });
  const authTitle = document.getElementById("auth-title");
  if (authTitle) authTitle.textContent = t("Sign in");
  const authBtn = document.getElementById("auth-btn");
  if (authBtn) authBtn.textContent = t("Sign in");
  document.querySelectorAll("#auth-screen label").forEach(l => {
    const node = [...l.childNodes].find(n => n.nodeType === 3 && n.textContent.trim());
    if (!node) return;
    if (!l.dataset.i18n) l.dataset.i18n = node.textContent.trim();
    node.textContent = t(l.dataset.i18n);
  });
}

/* language picker in the sidebar (above the credit) */
function initLangPicker() {
  const sidebar = document.querySelector(".sidebar");
  if (!sidebar || document.getElementById("lang-select")) return;
  const wrap = document.createElement("div");
  wrap.className = "lang-picker";
  wrap.innerHTML = `<label style="font-size:10.5px;letter-spacing:1px;text-transform:uppercase;color:var(--muted,#64748b)">🌐 <span id="lang-label">${t("Language")}</span></label>
    <select id="lang-select" aria-label="Language">${Object.entries(LANGS).map(([code, name]) =>
      `<option value="${code}" ${code === CUR_LANG ? "selected" : ""}>${name}</option>`).join("")}</select>`;
  const credit = sidebar.querySelector(".sidebar-credit");
  sidebar.insertBefore(wrap, credit || null);
  wrap.querySelector("#lang-select").addEventListener("change", (e) => {
    CUR_LANG = e.target.value;
    localStorage.setItem("nexacrew_lang", CUR_LANG);
    const lbl = document.getElementById("lang-label");
    if (lbl) lbl.textContent = t("Language");
    applyI18n();
    // re-render the current page so dynamic titles/content pick up the language
    if (typeof render === "function") { try { render(); } catch (err) { /* view not ready */ } }
  });
}

document.addEventListener("DOMContentLoaded", () => { initLangPicker(); applyI18n(); });
